function esc(s){return String(s==null?"":s).replace(/[&<>"']/g,function(c){return {"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c];});}
function inline(s){return nrefView(esc(s)).replace(/\*\*([^\n]+?)\*\*/g,'<strong>$1</strong>').replace(/==([^\n]+?)==/g,'<mark class="hl">$1</mark>').replace(/\u2028/g,"<br>");}
/* 말씀: 절 번호로 나누기 (1, 2, 3… 또는 22:1 형태, 번호가 차례로 이어질 때만) */
var CM="\uE000";
function verseCuts(t){var re=/(^|[\s(\uE000])(?:(\d{1,3}):)?(\d{1,3})(?:절)?[.)]?(?=[ \t\u00a0\n\u2028]|[^\s\d.,:~\-])/g,m,cuts=[],prev=null;
  while((m=re.exec(t))){var n=+m[3],at=m.index+m[1].length,k=at-1;while(k>=0&&t[k]===CM)k--;var lineStart=k<0||t[k]==="\n";if(n<1)continue;
    if(prev===null){if(!lineStart)continue;}else if(n!==prev+1)continue;
    cuts.push({at:at,end:m.index+m[0].length,label:(m[2]?m[2]+":":"")+n,tok:t.slice(at,m.index+m[0].length)});prev=n;}
  return cuts;}
function balanceParts(parts){var b=false,m=false;return parts.map(function(s){var x=(m?"==":"")+(b?"**":"")+s,re=/\*\*|==/g,mm,bb=false,mk=false;while((mm=re.exec(x))){if(mm[0]==="**")bb=!bb;else mk=!mk;}b=bb;m=mk;return x+(bb?"**":"")+(mk?"==":"");});}
function splitVerses(text){var t=String(text||""),cuts=verseCuts(t);
  if(!cuts.length)return null;var pre=t.slice(0,cuts[0].at).trim(),vs=cuts.map(function(c,i){return {n:c.label,t:t.slice(c.end,i+1<cuts.length?cuts[i+1].at:t.length).trim()};});var bal=balanceParts([pre].concat(vs.map(function(x){return x.t;})));pre=bal[0].replace(/^(\*\*|==)+$/,"");vs.forEach(function(x,k){x.t=bal[k+1];});return {pre:pre,vs:vs};}
function verses(text){var v=splitVerses(text);if(!v)return rich(text);var h='<div class="verses">';if(v.pre)h+='<div class="pre">'+rich(v.pre)+'</div>';
  v.vs.forEach(function(x){h+='<div class="vs"><span class="vn">'+esc(x.n)+'</span><span class="vt">'+x.t.split("\n").filter(function(q){return q.trim();}).map(function(q){return '<span class="vp">'+inline(q)+'</span>';}).join("")+'</span></div>';});return h+'</div>';}
function rich(body){var out="";String(body||"").split("\n").forEach(function(line){if(!line.trim())return;var segs=balanceParts(line.split("\u2028"));
    out+="<p>"+segs.map(function(sg){if(/^- /.test(sg))return '<span class="ln li"><span class="vb">•</span>'+inline(sg.slice(2))+'</span>';return '<span class="ln">'+(inline(sg)||"&nbsp;")+'</span>';}).join("")+"</p>";});return out;}
function today(){var d=new Date();return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");}
function fmtDate(d){var m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(d||"");if(!m)return d||"";var dt=new Date(+m[1],+m[2]-1,+m[3]);return m[1]+". "+(+m[2])+". "+(+m[3])+" ("+"일월화수목금토"[dt.getDay()]+")";}
function chapOf(ref){var s=String(ref||"");var m=/(\d+)\s*[:장]/.exec(s)||/(\d+)/.exec(s);return m?+m[1]:0;}
function uid(){return "b"+Date.now().toString(36)+Math.random().toString(36).slice(2,6);}
var KIND={word:"말씀",expl:"해설",serm:"설교",med:"묵상"};
/* 말씀 구절 → 대한성서공회 개역개정 본문 링크 */
var USFM={gen:"GEN",exo:"EXO",lev:"LEV",num:"NUM",deu:"DEU",josh:"JOS",judg:"JDG",ruth:"RUT","1sam":"1SA","2sam":"2SA","1kgs":"1KI","2kgs":"2KI","1chr":"1CH","2chr":"2CH",ezra:"EZR",neh:"NEH",esth:"EST",job:"JOB",ps:"PSA",prov:"PRO",eccl:"ECC",song:"SNG",isa:"ISA",jer:"JER",lam:"LAM",ezek:"EZK",dan:"DAN",hos:"HOS",joel:"JOL",amos:"AMO",obad:"OBA",jonah:"JON",mic:"MIC",nah:"NAM",hab:"HAB",zeph:"ZEP",hag:"HAG",zech:"ZEC",mal:"MAL",matt:"MAT",mark:"MRK",luke:"LUK",john:"JHN",acts:"ACT",rom:"ROM","1cor":"1CO","2cor":"2CO",gal:"GAL",eph:"EPH",phil:"PHP",col:"COL","1thess":"1TH","2thess":"2TH","1tim":"1TI","2tim":"2TI",titus:"TIT",phlm:"PHM",heb:"HEB",jas:"JAS","1pet":"1PE","2pet":"2PE","1john":"1JN","2john":"2JN","3john":"3JN",jude:"JUD",rev:"REV"};
var BYLEN=BIBLE.slice().sort(function(a,b){return b[1].length-a[1].length;});
function parseRef(ref,defBook){var s=String(ref||"").replace(/\s+/g,""),book=defBook;
  for(var i=0;i<BYLEN.length;i++){if(s.indexOf(BYLEN[i][1])===0){book=BYLEN[i][0];s=s.slice(BYLEN[i][1].length);break;}}
  if(!BMAP[book]||!USFM[book])return null;
  var m=/^(\d+)(?:편|장|:)(\d+)?절?(?:[~\-–](?:(\d+)(?:편|장|:))?(\d+)절?)?/.exec(s),ch,v1=0,ch2=0,v2=0;
  if(m){ch=+m[1];v1=m[2]?+m[2]:0;if(v1){ch2=m[3]?+m[3]:0;v2=m[4]?+m[4]:0;}}
  else{var m2=/^(\d+)(?:[~\-–]\d+)?(?:장|편)?$/.exec(s);if(!m2)return null;ch=+m2[1];}
  if(!ch||ch>BMAP[book].ch)return null;if(ch2&&(ch2<ch||ch2>BMAP[book].ch))ch2=0;
  var code=USFM[book],url="https://bible.bskorea.or.kr/bible/NKRV/"+code+"."+ch;
  if(v1)url+="."+v1+"-"+code+"."+(ch2||ch)+"."+(v2||v1);
  var unit=book==="ps"?"편":"장",label=BMAP[book].name+" "+(v1?ch+":"+v1+(v2?"~"+(ch2&&ch2!==ch?ch2+":":"")+v2:""):ch+unit);
  return {url:url,label:label};}


