var BOOKREGION={gen:"wide",exo:"egypt",lev:"egypt",num:"egypt",deu:"egypt",acts:"wide",rom:"wide","1cor":"wide","2cor":"wide",gal:"wide",eph:"wide",phil:"wide",col:"wide","1thess":"wide","2thess":"wide","1tim":"wide","2tim":"wide",titus:"wide",phlm:"wide",heb:"wide","1pet":"wide","2pet":"wide","1john":"wide","2john":"wide","3john":"wide",rev:"wide"};

/* 성경 전체: 특정 본문 없이 쓰는 기록용. 성경 전체의 큰 흐름 */
BOOKMAP.bible=[
 mkStage("b1",[-1,-1],"창세기","창조와 족장들",["ur","haran","shechem","hebron","egypt"],[["ur","haran","shechem","hebron"],["hebron","egypt",1]],"하나님이 세상을 창조하시고, 우상 섬기던 집안에서 아브라함을 불러 가나안으로 이끄신다. 약속은 이삭과 야곱으로 이어지고, 요셉 때 온 가족이 애굽으로 내려간다."),
 mkStage("b2",[-1,-1],"출애굽기~신명기","출애굽과 광야 40년",["rameses","redsea","sinai","kadesh","nebo"],[["rameses","redsea","sinai","kadesh",1],["kadesh","nebo",1]],"모세를 통해 애굽에서 건지시고, 시내산에서 언약과 율법을 주신다. 불순종한 세대는 광야에서 40년을 보내고, 새 세대가 모압 평지에서 약속의 땅을 바라본다."),
 mkStage("b3",[-1,-1],"여호수아~룻기","가나안 정복과 사사 시대",["shittim","jericho","ai","shiloh","hazor"],[["shittim","jericho","ai"]],"여호수아가 요단을 건너 땅을 정복하고 지파별로 나눈다. 실로에 성막을 두지만, 사사 시대에는 '각자 자기 소견에 옳은 대로' 행하는 일이 되풀이된다.",{tr:true}),
 mkStage("b4",[-1,-1],"사무엘상~역대하","통일 왕국",["ramah","gibeah","hebron","jerusalem"],[["hebron","jerusalem"]],"사무엘이 사울과 다윗에게 기름을 붓는다. 다윗은 헤브론에서 왕이 된 뒤 예루살렘을 도읍으로 삼고, 솔로몬이 그곳에 성전을 짓는다."),
 mkStage("b5",[-1,-1],"열왕기상하·선지서","나뉜 왕국과 선지자들",["dan","bethel","samaria","jerusalem","carmel"],[],"솔로몬 뒤 나라는 북이스라엘(사마리아)과 남유다(예루살렘)로 나뉜다. 북쪽은 단과 벧엘에 금송아지를 세우고, 엘리야와 엘리사, 여러 선지자가 돌아오라고 외친다."),
 mkStage("b6",[-1,-1],"열왕기하·예레미야·에스겔","앗수르와 바벨론 포로",["samaria","nineveh","jerusalem","babylon","chebar"],[["samaria","nineveh",1],["jerusalem","babylon",1]],"B.C. 722년 사마리아가 앗수르에 무너지고, B.C. 586년 예루살렘과 성전이 바벨론에 무너진다. 백성은 그발 강가 같은 포로지에서 새 언약의 약속을 듣는다."),
 mkStage("b7",[-1,-1],"에스라·느헤미야·에스더","포로에서 돌아오다",["babylon","susa","jerusalem"],[["babylon","jerusalem"]],"바사 왕 고레스의 칙령으로 백성이 돌아와 성전을 다시 짓고, 느헤미야가 성벽을 쌓는다. 수산 궁에서는 에스더를 통해 흩어진 백성이 보호받는다."),
 mkStage("b8",[-1,-1],"복음서","예수 그리스도",["bethlehem","nazareth","capernaum","jerusalem"],[["bethlehem","nazareth",1],["nazareth","capernaum"],["capernaum","jerusalem"]],"약속대로 예수님이 베들레헴에서 나시고 나사렛에서 자라신다. 갈릴리 가버나움을 중심으로 하나님 나라를 전하시고, 예루살렘에서 십자가에 죽으시고 부활하신다."),
 mkStage("b9",[-1,-1],"사도행전","복음이 땅끝까지",["jerusalem","antioch","ephesus","corinth","caesarea","rome"],[["jerusalem","antioch"],["antioch","ephesus","corinth"],["caesarea","rome",1]],"성령이 임하시고 교회가 예루살렘에서 시작된다. 안디옥 교회가 바울을 보내 소아시아와 그리스에 교회가 세워지고, 복음은 로마에까지 이른다."),
 mkStage("b10",[-1,-1],"서신서·요한계시록","교회와 새 하늘 새 땅",["rome","corinth","ephesus","philippi","patmos","jerusalem"],[],"사도들이 여러 교회에 편지를 보내 믿음과 삶을 세운다. 요한은 밧모섬에서 일곱 교회에 주시는 말씀과 새 하늘과 새 땅, 새 예루살렘의 환상을 기록한다.")
];
BOOKREGION.bible="wide";

