function nrefView(h){return h.replace(nrefRe(),function(_,id,lb){var gone=GOT&&!nrefFind(id);return '<a class="nref'+(gone?' gone':'')+'" href="#'+id+'" data-e="'+id+'" title="'+(gone?'지워졌거나 찾을 수 없는 말씀노트':'말씀노트로 이동')+'">'+lb+'</a>';});}
