  if(!rc||(!rc.left&&!rc.top&&!rc.height))rc=NR.ed.getBoundingClientRect();
  var box=NR.box,vw=window.innerWidth,vh=window.innerHeight,w=Math.min(360,vw-24);box.style.width=w+"px";
  var left=Math.max(12,Math.min(rc.left,vw-w-12)),bh=box.offsetHeight,top=rc.bottom+6;if(top+bh>vh-12&&rc.top-bh-6>12)top=rc.top-bh-6;
