  if(!n.parentNode||!ed.contains(n)){nrefClose();return;}
  var end=sel.anchorNode===n?sel.anchorOffset:Math.min(n.nodeValue.length,NR.start+1+NR.q.length);if(end<NR.start+1)end=Math.min(n.nodeValue.length,NR.start+1);
