var DLP=null;function dlGet(){if(!DLP){DLP=Promise.resolve().then(function(){return (window.claude&&window.claude.use)?window.claude.use("downloads"):null;}).catch(function(){return null;});}return DLP;}
function bkDate(){var d=new Date();return d.getFullYear()+"-"+String(d.getMonth()+1).padStart(2,"0")+"-"+String(d.getDate()).padStart(2,"0");}
function myEntries(){var a=[];for(var k in ENTRIES)a.push(ENTRIES[k]);a.sort(function(x,y){return String(y.date||"").localeCompare(String(x.date||""))||String(y.createdAt||"").localeCompare(String(x.createdAt||""));});return a;}
function myPrayers(){var a=[];for(var k in PRAYERS)a.push(PRAYERS[k]);a.sort(function(x,y){return String(y.date||"").localeCompare(String(x.date||""))||String(y.createdAt||"").localeCompare(String(x.createdAt||""));});return a;}
function clean(o){var c={};for(var k in o){if(k.charAt(0)==="_")continue;c[k]=o[k];}return c;}
function backupJSON(){var data={app:"말씀노트",format:1,exportedAt:new Date().toISOString(),profile:(ME&&PROFS[ME])?{role:PROFS[ME].role||"",bio:PROFS[ME].bio||""}:null,
    mottos:(typeof MVAL!=="undefined")?MVAL:{},entries:myEntries().map(clean),prayers:myPrayers().map(clean)};
  return JSON.stringify(data,null,2);}
var PLAB={sit:"상황",req:"기도제목",ans:"응답",img:"사진"};
function prayerText(p){var L=["[기도] "+(String(p.title||"").trim()||"제목 없는 기도")+" ("+(PCM[catOf(p)]||"기타")+" · "+(p.answered?"응답됨":"기도 중")+")"];
  var m=[];if(p.date)m.push("🗓 시작 "+fmtDate(p.date));if(p.answered&&p.answeredAt)m.push("응답 "+fmtDate(p.answeredAt));if(m.length)L.push(m.join(" · "));
  var t=L.join("\n");(p.blocks||[]).forEach(function(b){var k=PLAB[b.type]?b.type:"req";if(k==="img"){var n=(b.images||[]).length;if(n)t+="\n\n【사진】 "+n+"장"+(String(b.text||"").trim()?"\n"+cpRich(b.text):"");return;}
    var body=cpRich(b.text);if(!body.trim())return;var add=(k==="req"&&typeof blkDay==="function")?blkDay(b,p):"";t+="\n\n【"+PLAB[k]+"】"+(add?" ("+add+")":"")+"\n"+body;});
  return t;}
function backupText(){var es=myEntries(),ps=myPrayers(),line="\n\n━━━━━━━━━━━━━━\n\n";
  var t="말씀노트 백업 · "+fmtDate(bkDate())+"\n말씀노트 "+es.length+"개 · 기도 "+ps.length+"개";
  if(es.length)t+=line+"■ 말씀노트\n\n"+es.map(entryText).join(line);
  if(ps.length)t+=line+"■ 기도노트\n\n"+ps.map(prayerText).join(line);
  return t+"\n";}
var SETD=null;
