    '<div class="setrow"><button type="button" class="setbtn" data-bk="json"><span class="si">{ }</span><span class="st"><b>전체 백업</b><small>.json · 모든 기록이 그대로 담긴 원본 자료</small></span></button>'+
    '<button type="button" class="setbtn" data-bk="txt"><span class="si">Aa</span><span class="st"><b>읽기용 텍스트</b><small>.txt · 메모장이나 휴대폰에서 바로 읽기</small></span></button></div>'+
    '<p class="setnote">사진은 파일에 들어가지 않고 몇 장이 있었는지만 적혀요. 나눔 그룹의 다른 사람 글도 들어가지 않아요.</p><p class="setmsg" id="set-msg" aria-live="polite"></p></section>'+window.MN.settingsHTML()+
    '<div class="psact"><button type="button" class="btn" data-x="1">닫기</button></div></div>';
  document.body.appendChild(d);document.body.style.overflow="hidden";window.MN.wireSettings(d);
  function close(){if(!SETD)return;SETD.remove();SETD=null;document.body.style.overflow="";document.removeEventListener("keydown",k,true);try{if(back&&back.focus)back.focus();}catch(e){}}
