function renderTimeline(){var box=document.getElementById("timeline");if(!box)return;var cnt=countByBook(),n=0;
  var h=bookIntroHTML(cur)+'<div class="tlhead"><div class="tllegend">'+
    Object.keys(TLCAT).map(function(k){return '<span class="tc '+k+'">'+TLCAT[k]+'</span>';}).join("")+'</div></div><ol class="tl">';
  ERAS.forEach(function(er,ei){h+='<li class="era'+(er.b.length?'':' gap')+'"><div class="erahd"><span class="eradot" aria-hidden="true"></span><div><h3>'+esc(er.t)+'</h3><span class="eray">'+esc(er.y)+'</span></div></div><p class="erad">'+esc(er.d)+'</p>';
    if(er.b.length){h+='<div class="tlbooks">';er.b.forEach(function(x){var id=x[0],bk=BMAP[id];if(!bk)return;n++;var c=cnt[id]||0;
      h+='<div class="tlb '+tlCat(id)+(id===cur?' cur':'')+'"><button type="button" class="tlgo" data-b="'+id+'" title="'+esc(bk.name)+' 기록 보기"><span class="tln"><b>'+esc(bk.name)+'</b>'+(c?'<span class="tlcnt">'+c+'</span>':'')+'</span><span class="tlw">'+esc(x[1])+'</span><span class="tlx">'+esc(x[2])+'</span></button>'+
        (BOOKMAP[id]&&BOOKMAP[id].length?'<button type="button" class="tlmap" data-m="'+id+'" aria-label="'+esc(bk.name)+' 공간적 배경" title="공간적 배경"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 4L3 6.5v13.5l6-2.5 6 2.5 6-2.5V4l-6 2.5z"/><path d="M9 4v13.5M15 6.5V20"/></svg></button>':'')+'</div>';});h+='</div>';}
    h+='</li>';});
  h+='</ol><p class="tlnote">연대는 보수적인 복음주의 학계에서 널리 쓰는 추정이에요. 출애굽 연대, 욥기·요엘·오바댜의 시기처럼 견해가 나뉘는 책도 있어요.</p>';
  box.innerHTML=h;box.setAttribute("data-n",n);}
document.addEventListener("click",function(e){var bi=e.target.closest&&e.target.closest("#timeline [data-bi]");if(bi){setView(bi.getAttribute("data-bi"));return;}
  var g=e.target.closest&&e.target.closest("#timeline [data-b],#timeline [data-m]");if(!g)return;var id=g.getAttribute("data-b")||g.getAttribute("data-m"),toMap=g.hasAttribute("data-m");
  if(toMap){if(id!==cur)selectBook(id);setView("map");return;}
  if(id!==cur)selectBook(id);renderTimeline();var top=document.getElementById("view-time").getBoundingClientRect().top+window.scrollY-(parseFloat(getComputedStyle(document.documentElement).getPropertyValue("--stickh"))||0)-8;window.scrollTo({top:Math.max(0,top),behavior:"instant"});
  var t2=document.getElementById("bi-t");if(t2){t2.setAttribute("tabindex","-1");try{t2.focus({preventScroll:true});}catch(z){}}});

/* ---------- 책 소개: [저자, 기록 시기, 받는 사람, 시대적 배경, 기록 목적, 핵심 구절] ---------- */
var BINFO={
bible:["약 40명 (모세, 다윗, 선지자, 사도 등)과 성령의 감동","약 1,500년 (B.C. 1400년대 ~ A.D. 95년경)","하나님의 백성과 모든 사람","아시아·아프리카·유럽 세 대륙에서 히브리어·아람어·헬라어로 기록되었어요. 구약 39권과 신약 27권, 모두 66권이에요.","창조 → 타락 → 구속 → 완성의 큰 이야기를 통해, 예수 그리스도 안에서 주시는 구원을 알게 하려는 책이에요.","딤후 3:16~17"],
gen:["모세 (전통적 견해)","B.C. 1446~1406년경, 광야에서","광야의 이스라엘 백성","창조부터 요셉의 죽음까지, 이스라엘이 한 민족이 되기 전의 역사예요. 메소포타미아에서 가나안, 애굽으로 이어지는 족장들의 이야기가 담겨 있어요.","하나님이 세상을 지으시고, 죄로 무너진 세상을 위해 아브라함과 언약을 맺어 구원의 역사를 시작하셨음을 알려요. 이스라엘이 누구이며 왜 부르심을 받았는지 보여 줘요.","창 12:1~3"],
exo:["모세","B.C. 1446~1406년경, 광야에서","광야의 이스라엘 백성","요셉이 죽은 뒤 수백 년 동안 이스라엘은 애굽에서 크게 번성했지만, 새 왕조 아래서 종살이하며 고통받았어요.","애굽에서 백성을 건지신 구원의 하나님, 시내산 언약과 율법, 그리고 성막을 통해 백성 가운데 거하시는 하나님을 보여 줘요.","출 19:5~6"],
lev:["모세","B.C. 1445년경, 시내산에서","제사장과 이스라엘 백성","성막이 완성된 직후, 백성이 시내산 아래 머물던 약 한 달 동안 주신 말씀이에요.","거룩하신 하나님께 나아가는 길(제사)과, 구원받은 백성이 거룩하게 사는 법(정결·절기·이웃 사랑)을 가르쳐요.","레 19:2"],
num:["모세","B.C. 1406년경, 모압 평지에서","가나안을 앞둔 새 세대","시내산을 떠나 모압 평지에 이르기까지 약 38년의 광야 여정이에요. 두 번의 인구 조사가 출애굽 세대와 새 세대를 나눠요.","불신앙이 가져온 결과를 보여 주면서도, 그럼에도 약속을 지키시는 하나님을 증언하고 새 세대를 준비시켜요.","민 14:8~9"],
deu:["모세 (마지막 장은 후대에 덧붙인 것으로 봄)","B.C. 1406년경, 모압 평지에서","요단을 건널 새 세대","모세가 죽기 직전, 요단 동편 모압 평지에서 한 세 편의 설교예요. 광야에서 자란 세대가 약속의 땅 앞에 서 있었어요.","언약을 새롭게 하며, 하나님을 마음을 다해 사랑하고 말씀에 순종하라고 권면해요. 순종에 따르는 복과 불순종에 따르는 저주도 알려요.","신 6:4~5"],
josh:["여호수아 (일부는 후대 기록, 전통적 견해)","B.C. 1390년경","가나안에 들어간 이스라엘","모세가 죽은 뒤 여호수아가 백성을 이끌고 요단을 건너 가나안을 정복하고, 땅을 지파별로 나눈 시기예요 (B.C. 1406~1390년경).","조상들에게 하신 약속을 하나도 어기지 않고 이루시는 하나님의 신실하심과, 말씀에 순종하는 삶의 중요성을 보여 줘요.","수 1:8~9"],
judg:["미상 (전통적으로 사무엘)","B.C. 1050~1000년경, 왕정 초기","이스라엘 백성","여호수아가 죽은 뒤 왕이 세워지기까지 약 300년이에요. 지파들은 흩어져 살았고, 주변 민족의 압제가 되풀이되었어요.","하나님을 떠난 백성이 겪는 죄 → 압제 → 부르짖음 → 구원의 순환을 보여 주며, 참된 왕이 필요하다는 것을 드러내요.","삿 21:25"],
ruth:["미상 (전통적으로 사무엘)","다윗 시대 이후","이스라엘 백성","사사 시대, 베들레헴에 기근이 들어 한 가족이 모압으로 떠나며 이야기가 시작돼요.","이방 여인 룻의 신실함과 기업 무를 자 보아스의 사랑을 통해, 다윗 왕가를 예비하신 하나님의 섭리를 보여 줘요.","룻 1:16"],
"1sam":["미상 (사무엘·나단·갓의 기록을 바탕으로 함, 대상 29:29)","왕국이 나뉜 뒤","이스라엘 백성","사사 시대가 끝날 무렵 블레셋의 압박 속에서 백성이 왕을 구하고, 왕정이 시작돼요 (B.C. 1100~1010년경).","사울에서 다윗으로 왕권이 옮겨 가는 과정을 통해, 하나님이 보시는 왕의 기준은 외모가 아니라 마음 중심임을 보여 줘요.","삼상 16:7"],
"2sam":["미상 (사무엘하와 한 권이었음)","왕국이 나뉜 뒤","이스라엘 백성","다윗이 헤브론과 예루살렘에서 다스린 40년이에요 (B.C. 1010~970년경).","다윗과 맺으신 영원한 언약(7장)을 중심으로, 하나님의 은혜와 죄가 가져오는 아픈 결과를 함께 보여 줘요.","삼하 7:12~16"],
"1kgs":["미상 (전통적으로 예레미야)","B.C. 560~540년경, 포로기","바벨론 포로 된 백성","솔로몬의 즉위와 성전 건축, 왕국의 분열, 아합 시대 엘리야의 사역까지예요 (B.C. 970~850년경).","왕국이 무너진 까닭이 언약을 떠난 데 있음을 보여 주고, 포로 된 백성을 회개와 소망으로 불러요.","왕상 18:21"],
"2kgs":["미상 (전통적으로 예레미야)","B.C. 560~540년경, 포로기","바벨론 포로 된 백성","엘리사의 사역부터 북이스라엘의 멸망(722)과 남유다의 멸망(586)까지예요.","선지자들의 거듭된 경고에도 돌아오지 않은 결과를 보여 주면서, 다윗의 등불을 끄지 않으시는 하나님의 약속을 남겨요.","왕하 17:13"],
"1chr":["전통적으로 에스라","B.C. 450~400년경, 포로 귀환 후","포로에서 돌아온 백성","아담부터 이어지는 족보와 다윗의 통치를 다시 들려줘요. 성전 예배 준비에 특히 무게를 두어요.","돌아온 공동체에게 자신들이 언약 백성의 줄기에 있으며, 다윗 언약과 성전 예배가 여전히 살아 있음을 일깨워요.","대상 17:11~14"],
"2chr":["전통적으로 에스라","B.C. 450~400년경, 포로 귀환 후","포로에서 돌아온 백성","솔로몬부터 바벨론 포로, 고레스의 귀환 칙령까지 유다 왕들의 역사예요.","성전과 회개를 중심으로 역사를 다시 읽으며, 겸손히 돌아오는 자를 회복시키시는 하나님을 보여 줘요.","대하 7:14"],
ezra:["에스라 (제사장이자 학자)","B.C. 440년경","포로에서 돌아온 백성","바사 시대예요. 고레스 칙령(538)으로 1차 귀환이 이뤄져 성전이 재건되고(516), 수십 년 뒤 에스라가 돌아와요(458).","약속대로 백성을 돌아오게 하신 하나님과, 말씀을 중심으로 공동체를 다시 세우는 과정을 보여 줘요.","스 7:10"],
neh:["느헤미야 (에스라와 함께 편집된 것으로 봄)","B.C. 430년경","예루살렘에 돌아온 백성","아닥사스다 왕의 술 맡은 관원이던 느헤미야가, 무너진 예루살렘 성벽 소식을 듣고 돌아와요 (B.C. 445년).","기도와 행동으로 성벽을 다시 쌓고 말씀 앞에서 언약을 새롭게 하는, 하나님 백성의 회복을 보여 줘요.","느 8:10"],
esth:["미상 (모르드개라는 견해도 있음)","B.C. 460~350년경","바사에 흩어진 유대인","아하수에로(크세르크세스) 왕 때 바사의 수도 수산이 무대예요 (B.C. 483~473년).","하나님의 이름이 한 번도 나오지 않지만, 보이지 않게 일하시며 백성을 지키시는 섭리를 보여 줘요. 부림절이 생긴 이유도 알려요.","에 4:14"],
job:["미상","연대 논란 (족장 시대를 배경으로 봄)","하나님의 백성","우스 땅에 살던 의인 욥이 재산과 자녀와 건강을 모두 잃는 이야기예요.","의인이 받는 고난이라는 질문을 정면으로 다루며, 답은 설명이 아니라 하나님 자신을 만나는 데 있음을 보여 줘요.","욥 42:5"],
ps:["다윗(73편)을 비롯해 아삽, 고라 자손, 솔로몬, 모세 등","모세 때부터 포로 후까지 약 1,000년","이스라엘의 예배 공동체","개인과 공동체가 겪은 기쁨, 고난, 죄, 회복의 여러 순간에 드린 노래와 기도예요. 다섯 권으로 나뉘어 있어요.","찬양·탄식·감사·회개를 하나님께 그대로 올려 드리는 기도의 책이며, 오실 메시아를 바라보게 해요.","시 1:1~2"],
prov:["대부분 솔로몬, 아굴과 르무엘 등","솔로몬 시대, 히스기야 때 일부 편집 (25:1)","젊은이와 백성","통일 왕국이 가장 번영하던 시기에 모인 지혜의 말씀이에요.","여호와를 경외하는 것에 뿌리내린 지혜로 말, 일, 돈, 가정, 관계 같은 일상을 바르게 살도록 가르쳐요.","잠 1:7"],
eccl:["전도자 (전통적으로 솔로몬)","B.C. 935년경 (전통적 견해)","하나님의 백성","모든 것을 누려 본 왕이 인생을 돌아보며 성찰한 기록이에요.","해 아래 모든 것의 헛됨을 정직하게 보여 주며, 하나님을 경외하고 그 명령을 지키는 것이 사람의 본분임을 말해요.","전 12:13"],
song:["솔로몬","솔로몬 통치 초기","하나님의 백성","신랑과 술람미 여인이 주고받는 사랑의 노래예요.","하나님이 주신 사랑과 결혼의 아름다움을 노래해요. 하나님과 백성, 그리스도와 교회의 사랑을 보여 주는 그림으로도 읽어요.","아 8:6~7"],
isa:["이사야","B.C. 740~680년경","유다와 예루살렘","웃시야부터 히스기야 시대까지, 앗수르가 북이스라엘을 무너뜨리고 유다를 위협하던 때예요.","거룩하신 하나님의 심판과 위로를 함께 전하며, 고난받는 종 메시아와 새 하늘과 새 땅을 약속해요.","사 53:5~6"],
jer:["예레미야 (서기관 바룩이 받아 적음)","B.C. 627~580년경","유다와 예루살렘","요시야부터 시드기야 시대까지, 바벨론이 일어나 예루살렘을 무너뜨린 때예요.","끝까지 돌아오라고 눈물로 외치고, 심판 너머에 마음에 새겨질 새 언약을 약속해요.","렘 31:31~33"],
lam:["전통적으로 예레미야","B.C. 586년 직후","무너진 예루살렘의 백성","바벨론에 의해 예루살렘과 성전이 불타고 백성이 끌려간 직후예요.","무너진 현실 앞에서 정직하게 애통하면서도, 아침마다 새로운 하나님의 긍휼을 붙들게 해요.","애 3:22~23"],
ezek:["에스겔 (제사장)","B.C. 593~571년, 바벨론에서","바벨론에 포로 된 백성","597년 2차 포로 때 끌려간 사람들이 그발 강가에 살던 때예요. 예루살렘은 아직 무너지기 전이었어요.","하나님의 영광이 성전을 떠나는 심판과, 새 마음과 새 영을 주셔서 다시 살리시는 회복을 보여 줘요.","겔 36:26~27"],
dan:["다니엘","B.C. 530년경","포로 된 백성","바벨론 느부갓네살부터 바사 고레스까지, 포로지의 왕궁이 무대예요 (B.C. 605~536년).","이방 제국 아래서도 역사를 다스리시는 하나님과, 끝내 세워질 영원한 나라를 보여 줘요.","단 2:44"],
hos:["호세아","B.C. 750~715년","북이스라엘","여로보암 2세 때의 번영 뒤에 우상숭배와 타락이 깊어지고, 앗수르가 다가오던 때예요.","음란한 아내를 다시 사랑하는 호세아의 삶처럼, 배신한 백성을 끝까지 사랑하시는 하나님을 보여 줘요.","호 6:6"],
joel:["요엘","연대 논란 (B.C. 9세기 또는 포로 후)","유다","큰 메뚜기 재앙이 땅을 휩쓴 뒤예요.","여호와의 날 앞에서 마음을 찢고 돌아오라고 부르며, 모든 사람에게 성령을 부어 주시리라 약속해요.","욜 2:28~29"],
amos:["아모스 (드고아의 목자)","B.C. 760년경","북이스라엘","여로보암 2세 때 경제는 번영했지만, 가난한 사람을 짓밟는 불의가 가득했어요.","형식만 남은 예배를 꾸짖고, 정의와 공의를 강물처럼 흐르게 하라고 요구해요.","암 5:24"],
obad:["오바댜","B.C. 586년 무렵 (다른 견해 있음)","유다 (에돔에 대한 예언)","예루살렘이 무너질 때 형제 나라 에돔이 기뻐하며 유다를 해쳤어요.","교만한 에돔의 심판과 시온의 회복을 선포하며, 나라가 여호와께 속할 것을 말해요.","옵 1:15"],
jonah:["요나 (전통적 견해)","B.C. 780년경","이스라엘","여로보암 2세 때, 앗수르의 수도 니느웨가 강성하던 시기예요.","원수 나라까지 아끼시는 하나님의 긍휼과, 그 긍휼을 받아들이지 못하는 선지자의 좁은 마음을 보여 줘요.","욘 4:11"],
mic:["미가 (모레셋 사람)","B.C. 735~700년","유다와 이스라엘","요담·아하스·히스기야 시대, 지도자와 부자들의 불의가 심하던 때예요.","심판과 회복을 함께 전하며, 베들레헴에서 나실 통치자를 약속해요. 하나님이 구하시는 것은 정의와 인자와 겸손이에요.","미 6:8"],
nah:["나훔","B.C. 663~612년","유다","앗수르가 애굽의 테베를 무너뜨린(663) 뒤, 니느웨가 멸망(612)하기 전이에요.","잔인한 앗수르의 수도 니느웨가 심판받을 것을 알려, 억눌린 유다를 위로해요.","나 1:7"],
hab:["하박국","B.C. 609~597년","유다","바벨론이 새 강대국으로 떠오르던 때예요.","\"왜 악을 그냥 두십니까\"라는 질문에 대한 하나님의 답을 담고 있어요. 의인은 믿음으로 살고, 어떤 형편에서도 여호와로 즐거워해요.","합 2:4"],
zeph:["스바냐 (히스기야의 현손)","B.C. 640~621년","유다","요시야 왕의 개혁 이전, 우상숭배가 가득하던 때예요.","다가올 여호와의 날을 경고하고, 남은 자를 기뻐하며 노래하시는 하나님을 보여 줘요.","습 3:17"],
hag:["학개","B.C. 520년","포로에서 돌아온 백성","다리오 왕 2년이에요. 성전 공사가 약 16년 동안 멈춰 있었어요.","자기 집보다 하나님의 집을 먼저 세우라고, 성전 건축을 다시 시작하라고 격려해요.","학 1:8"],
zech:["스가랴 (제사장 가문)","B.C. 520~480년경","포로에서 돌아온 백성","학개와 같은 시기에 성전 재건을 격려한 선지자예요.","여러 환상으로 회복을 약속하고, 나귀를 타고 오실 겸손한 왕 메시아를 예언해요.","슥 4:6"],
mal:["말라기","B.C. 430년경","포로에서 돌아온 백성","느헤미야 무렵, 성전은 세워졌지만 예배는 형식적이고 마음은 식어 있었어요.","하나님의 사랑을 의심하는 백성을 깨우고, 주의 날 전에 엘리야(세례 요한)를 보내시리라 약속해요.","말 4:5~6"],
matt:["마태 (세리 출신 사도)","A.D. 60년대","유대인 그리스도인","로마의 지배 아래 메시아를 기다리던 유대 땅이에요.","예수님이 구약의 예언을 이루신 메시아 왕이시며, 하나님 나라를 가르치시고 제자 삼으라 명하셨음을 증언해요.","마 28:18~20"],
mark:["마가 요한 (베드로의 증언을 바탕으로)","A.D. 50년대 후반~60년대","로마의 이방인 그리스도인","네로 황제의 박해가 다가오던 무렵이에요.","섬기러 오시고 대속물로 목숨을 주신 하나님의 아들 예수님을, 빠르고 생생하게 보여 줘요.","막 10:45"],
luke:["누가 (의사, 바울의 동역자)","A.D. 60년대","데오빌로 (이방인 독자)","로마 제국 전체를 바라보며 쓴 복음서예요. 사도행전과 짝을 이루어요.","모든 일을 차례대로 조사해, 가난한 자와 이방인을 포함한 모든 사람의 구주 예수님을 확실히 알게 해요.","눅 19:10"],
john:["사도 요한","A.D. 85~90년경, 에베소","교회 전체","예루살렘 성전이 무너진(A.D. 70) 뒤, 예수님이 누구신지에 대한 질문이 많던 때예요.","표적과 말씀을 통해 예수님이 하나님의 아들 그리스도이심을 믿고, 그 이름으로 생명을 얻게 하려고 기록했어요.","요 20:31"],
acts:["누가","A.D. 62년경","데오빌로","오순절부터 바울이 로마에서 가택 연금되기까지 약 30년이에요.","성령의 능력으로 복음이 예루살렘과 유대, 사마리아를 지나 땅끝까지 퍼져 가는 과정을 기록해요.","행 1:8"],
rom:["바울","A.D. 57년경, 고린도에서","로마 교회 (유대인과 이방인)","3차 선교 여행을 마칠 무렵, 바울은 로마를 거쳐 스페인으로 가려 했어요.","믿음으로 의롭다 하심을 얻는 복음을 차례대로 설명하고, 유대인과 이방인이 한 교회로 연합하게 해요.","롬 1:16~17"],
"1cor":["바울","A.D. 55년경, 에베소에서","고린도 교회","항구 도시 고린도의 교회에 분쟁, 음행, 소송, 우상 제물, 은사 문제가 생겼어요.","문제 하나하나를 십자가의 지혜로 바로잡고, 무엇보다 사랑으로 교회를 세우라고 가르쳐요.","고전 13:13"],
"2cor":["바울","A.D. 56년경, 마게도냐에서","고린도 교회","거짓 사도들이 바울의 사도권을 공격하고 있었어요.","자신의 사도직을 변호하며, 약할 때 강함이 되는 은혜와 예루살렘 성도를 위한 연보를 말해요.","고후 12:9"],
gal:["바울","A.D. 49년경 (남갈라디아설)","갈라디아 지방의 교회들","이방인 신자에게도 할례와 율법을 지켜야 한다고 주장하는 사람들이 들어왔어요.","율법의 행위가 아니라 믿음으로 의롭게 된다는 복음을 지키고, 성령 안에서 누리는 자유를 가르쳐요.","갈 2:20"],
eph:["바울","A.D. 60~62년, 로마 옥중","에베소와 주변 교회","바울이 처음 로마에 갇혀 있던 때예요.","그리스도 안에서 받은 영적인 복과, 유대인과 이방인이 하나 된 교회, 새 사람으로 사는 삶을 보여 줘요.","엡 2:8~10"],
phil:["바울","A.D. 61~62년, 로마 옥중","빌립보 교회","빌립보 교회가 보낸 선교 후원에 감사하며 쓴 편지예요.","갇힌 중에도 누리는 기쁨과, 자기를 낮추신 그리스도의 마음을 본받으라고 권면해요.","빌 4:4"],
col:["바울","A.D. 60~62년, 로마 옥중","골로새 교회","철학과 규례, 천사 숭배를 섞은 거짓 가르침이 들어왔어요.","만물보다 뛰어나신 그리스도 한 분으로 충분함을 밝히고, 그분 안에서 사는 삶을 가르쳐요.","골 2:9~10"],
"1thess":["바울","A.D. 50~51년, 고린도에서","데살로니가 교회","2차 선교 여행 때 세운 지 몇 달 안 된 교회가 박해를 받고 있었어요.","믿음과 사랑을 칭찬하고 격려하며, 주님의 재림과 먼저 잠든 성도에 대한 소망을 알려요.","살전 5:16~18"],
"2thess":["바울","A.D. 51년경, 고린도에서","데살로니가 교회","주의 날이 이미 왔다는 잘못된 소문 때문에 혼란스러워하고 일하지 않는 사람도 생겼어요.","재림 전에 있을 일들을 바로 알려 주고, 흔들리지 말고 성실하게 살라고 권면해요.","살후 2:15"],
"1tim":["바울","A.D. 62~64년, 1차 석방 뒤","디모데 (에베소 교회)","에베소 교회에 거짓 교사들이 일어났어요.","교회의 질서와 지도자의 자격, 바른 교훈과 경건을 가르쳐 교회를 진리의 기둥으로 세우게 해요.","딤전 3:15"],
"2tim":["바울","A.D. 67년경, 로마 옥중 (순교 직전)","디모데","네로의 박해 속에 다시 갇힌 바울이 남긴 마지막 편지예요.","복음을 위해 고난을 함께 받고, 어떤 때든지 말씀을 전하라고 사랑하는 제자에게 부탁해요.","딤후 4:2"],
titus:["바울","A.D. 63~65년","디도 (그레데 교회)","그레데 섬의 교회들을 바로 세우는 일이 디도에게 맡겨졌어요.","장로를 세우고, 바른 교훈에 맞게 선한 일에 힘쓰는 삶을 가르쳐요.","딛 2:11~12"],
phlm:["바울","A.D. 60~62년, 로마 옥중","빌레몬 (골로새 교회)","빌레몬에게서 도망친 종 오네시모가 바울을 만나 그리스도인이 되었어요.","오네시모를 종이 아니라 사랑받는 형제로 받아 달라고 부탁하며, 복음이 관계를 어떻게 바꾸는지 보여 줘요.","몬 1:16"],
heb:["미상 (바울, 바나바, 아볼로 등 여러 견해)","A.D. 60년대 (성전 파괴 전)","유대인 그리스도인","박해와 낙심 속에서 옛 제사 제도로 돌아가려는 유혹이 있었어요.","천사와 모세와 옛 제사보다 더 나은 대제사장 예수님을 보여 주며, 믿음을 끝까지 붙들라고 권면해요.","히 12:2"],
jas:["야고보 (예수님의 동생)","A.D. 45~49년경","흩어진 유대인 그리스도인","예루살렘 밖으로 흩어진 성도들이 가난과 시험을 겪고 있었어요.","말뿐인 믿음이 아니라, 시험을 견디고 행함으로 드러나는 살아 있는 믿음을 가르쳐요.","약 2:17"],
"1pet":["베드로 (실루아노가 받아 적음)","A.D. 64년경, 로마('바벨론')에서","소아시아에 흩어진 나그네 된 성도","네로 황제의 박해가 시작되기 직전이에요.","고난 가운데서도 산 소망을 붙들고, 택하신 족속답게 거룩하게 살라고 격려해요.","벧전 2:9"],
"2pet":["베드로","A.D. 67년경, 순교 직전","베드로전서와 같은 성도들","교회 안에 거짓 교사가 일어나고, 주님의 재림을 조롱하는 사람들이 있었어요.","거짓 가르침을 경계하고, 주의 날이 더딘 것은 오래 참으심 때문임을 알려 거룩하게 기다리게 해요.","벧후 3:9"],
"1john":["사도 요한","A.D. 85~95년경, 에베소","소아시아의 교회들","예수님이 육체로 오셨다는 것을 부인하는 거짓 가르침이 퍼지고 있었어요.","하나님과의 사귐과 구원의 확신을 주며, 빛과 진리와 사랑 가운데 행하라고 권면해요.","요일 4:7~8"],
"2john":["사도 요한 (\"장로\")","A.D. 85~95년경","택하심을 받은 부녀와 그 자녀들 (한 교회로 봄)","거짓 교사들이 교회를 돌아다니며 대접을 받고 있었어요.","진리 안에서 서로 사랑하되, 그리스도를 부인하는 가르침은 받아들이지 말라고 해요.","요이 1:6"],
"3john":["사도 요한 (\"장로\")","A.D. 85~95년경","가이오","순회 전도자들을 대접하는 문제로, 교만한 디오드레베가 교회를 어지럽히고 있었어요.","진리를 위해 수고하는 사람들을 기쁘게 대접하는 가이오를 칭찬하며, 선을 본받으라고 해요.","요삼 1:4"],
jude:["유다 (예수님의 동생, 야고보의 형제)","A.D. 65~80년경","부르심을 받은 성도들","하나님의 은혜를 방종의 핑계로 삼는 거짓 교사들이 몰래 들어왔어요.","믿음의 도를 위해 힘써 싸우고, 하나님의 사랑 안에서 자신을 지키라고 권면해요.","유 1:3"],
rev:["사도 요한","A.D. 95년경, 밧모섬","소아시아의 일곱 교회","도미티아누스 황제 때 황제 숭배를 거부한 그리스도인들이 박해를 받았어요.","이미 이기신 어린양과 장차 이루어질 새 하늘과 새 땅을 보여 주며, 박해받는 교회가 끝까지 이기도록 격려해요.","계 21:3~4"]
};
var BINFO_LAB=["저자","기록 시기","받는 사람","시대적 배경","기록 목적","핵심 구절"];
function eraOf(id){for(var i=0;i<ERAS.length;i++){for(var j=0;j<ERAS[i].b.length;j++){if(ERAS[i].b[j][0]===id)return ERAS[i];}}return null;}
function bookIntroHTML(id){var bk=BMAP[id],x=BINFO[id];if(!bk||!x)return "";var cat=id==="bible"?"":tlCat(id),er=eraOf(id);
  var pos=id==="bible"?"구약 39권 · 신약 27권":(bk.order<39?"구약 "+(bk.order+1)+"번째 책":"신약 "+(bk.order-38)+"번째 책")+" · "+bk.ch+(id==="ps"?"편":"장");
  var kv=x[5],kref=null;try{kref=parseRef(kv.replace(/^(\S+)\s/,function(m,a){return (ABBR[a]||a)+" ";}),id);}catch(e){}
  var h='<section class="bintro'+(cat?' '+cat:'')+'" aria-labelledby="bi-t"><div class="bihd"><div><h2 id="bi-t">'+esc(bk.name)+'</h2><div class="bimeta">'+(cat?'<span class="tc '+cat+'">'+TLCAT[cat]+'</span>':'')+'<span>'+esc(pos)+'</span>'+(er?'<span>'+esc(er.t)+'</span>':'')+'</div></div>'+
    '<div class="biacts"><button type="button" class="btn" data-bi="qt">기록 보기</button>'+(BOOKMAP[id]&&BOOKMAP[id].length?'<button type="button" class="btn" data-bi="map">공간적 배경</button>':'')+'</div></div><dl class="bigrid">';
  [0,1,2].forEach(function(i){h+='<div class="bif"><dt>'+BINFO_LAB[i]+'</dt><dd>'+esc(x[i])+'</dd></div>';});
  h+='<div class="bif wide"><dt>'+BINFO_LAB[3]+'</dt><dd>'+esc(x[3])+'</dd></div><div class="bif wide"><dt>'+BINFO_LAB[4]+'</dt><dd>'+esc(x[4])+'</dd></div>';
  h+='<div class="bif"><dt>'+BINFO_LAB[5]+'</dt><dd>'+(kref?'<a href="'+esc(kref.url)+'" target="_blank" rel="noopener noreferrer" title="대한성서공회 개역개정으로 읽기">'+esc(kv)+' ↗</a>':esc(kv))+'</dd></div></dl></section>';
  return h;}
